"""ARENA u10 的 10 道测验（沿用旧版题目，仅去掉解释里的位置引用）"""
from unitlib import Q
QUIZ = [
  Q("运行下面的代码，打印的 `args` 和 `kwargs` 分别是什么？\n\n```text\ndef f(*args, **kwargs):\n    print(args, kwargs)\n\nf(1, 2, lr=0.1)\n```", ["`[1, 2]` 和 `['lr', 0.1]`", "`(1, 2)` 和 `{'lr': 0.1}`", '`{1, 2}` 和 `(lr, 0.1)`', '`1` 和 `2`'], 1, '`args` 收集位置参数，是元组；`kwargs` 收集关键字参数，是字典。'),
  Q("运行下面的代码，打印什么？\n\n```text\nprint([x * 2 for x in range(4) if x != 2])\n```", ['`[0, 2, 6]`', '`[0, 2, 4, 6]`', '`[2, 6]`', '`[0, 1, 3]`'], 0, '`range(4)` 是 0, 1, 2, 3，去掉 2 后剩 0, 1, 3，每个乘 2 得 `[0, 2, 6]`。'),
  Q('`for ... else` 结构中，`else` 块什么时候执行？', ['循环体至少执行一次时', '循环中出现异常时', '循环被 `break` 打断时', '循环正常结束、**没有**被 `break` 打断时'], 3, '`else` 只在循环「跑完了没被 break」时执行，常用来写「找了一圈没找到」的逻辑。'),
  Q("运行下面的代码，第二个 `print` 打印什么？\n\n```text\ndef add(item, box=[]):\n    box.append(item)\n    return box\n\nprint(add(1))\nprint(add(2))\n```", ['`[2]`', '`[1]`', '`[1, 2]`', '报错'], 2, '默认值 `[]` 只在定义时创建一次，两次调用共用同一个列表。这是经典的可变默认参数陷阱。'),
  Q("运行下面的代码，打印的形状是什么？\n\n```text\nimport numpy as np\na = np.arange(12).reshape(3, 4)\nprint(a.sum(axis=1).shape)\n```", ['`(3,)`', '`(4,)`', '`(3, 4)`', '`(1,)`'], 0, '`axis=1` 表示把第 1 维（大小 4）消掉，剩下 `(3,)`，是每一行的和。'),
  Q('同一个 `a`，`a[:, 1]` 取出的是？', ['第 1 行 `[4, 5, 6, 7]`', '第 1 列 `[1, 5, 9]`', '`[0, 1]`', '整个数组'], 1, '`:` 表示所有行，`1` 表示第 1 列（从 0 开始数），所以是 `[1, 5, 9]`。'),
  Q("运行下面的代码，打印什么？\n\n```text\nimport numpy as np\na = np.arange(12).reshape(3, 4)\nb = a[0]\nb[0] = 100\nprint(a[0, 0])\n```", ['0', '报错', '取决于 dtype', '100'], 3, '基本切片返回**视图**，和原数组共享内存，改 `b` 就是改 `a`。想要独立的数据要用 `.copy()`（PyTorch 里是 `.clone()`）。'),
  Q('`a[a > 6]` 做的是什么？', ['把大于 6 的元素改成 True', '返回所有大于 6 的元素组成的一维数组', '返回大于 6 的元素的个数', '报错，不能用比较结果做索引'], 1, '`a > 6` 生成同形状的布尔数组，用它做索引就是**布尔掩码**，取出所有为 True 位置的元素。'),
  Q('对两个形状都是 `(3, 3)` 的 NumPy 数组，`A * B` 和 `A @ B` 的区别是？', ['`*` 是逐元素乘法，`@` 是矩阵乘法', '两者完全相同', '`*` 是矩阵乘法，`@` 是逐元素乘法', '`@` 只能用于向量'], 0, '`*` 对应位置相乘；`@` 是行乘列再求和的矩阵乘法。混淆两者是很常见的 bug，而且形状相同时不会报错。'),
  Q('为什么在 NumPy / PyTorch 里要尽量**向量化**，而不是写 Python 循环？', ['因为 Python 不支持循环', '因为向量化结果更精确', '因为数组运算在底层 C 代码里批量完成，快得多', '因为循环会改变数组的形状'], 2, '向量化把整批计算交给底层优化过的代码（以及 GPU），比逐个元素的 Python 循环快几十到上百倍。'),
]
